<?php
declare(strict_types=1);
namespace App\Application\Taxonomy\Service;
use App\Application\Study\Port\TransactionManagerInterface;use App\Application\Taxonomy\DTO\Request\UpdateTaxonomySubjectRequestDto;use App\Application\Taxonomy\DTO\Response\TaxonomySubjectResponseDto;use App\Application\Taxonomy\Mapper\TaxonomySubjectResponseMapper;use App\Domain\Taxonomy\Entity\TaxonomySubject;use App\Domain\Taxonomy\Repository\TaxonomySubjectRepositoryInterface;use App\Domain\Taxonomy\Service\SubjectTaxonomyService;
final class UpdateTaxonomySubjectService { public function __construct(private readonly TaxonomySubjectRepositoryInterface $subjects,private readonly SubjectTaxonomyService $taxonomy,private readonly TaxonomySubjectResponseMapper $mapper,private readonly TransactionManagerInterface $transactions){} public function update(UpdateTaxonomySubjectRequestDto $input):TaxonomySubjectResponseDto{return $this->transactions->transactional(function()use($input){$current=$this->subjects->findById($input->id);if($current===null)throw new \DomainException('Assunto nao encontrado.');if($current->parentId!==$input->parentId&&$this->subjects->hasChildren($current->id))throw new \DomainException('Mova primeiro os assuntos filhos antes de alterar o pai.');$parent=$input->parentId===null?null:$this->subjects->findById($input->parentId);if($input->parentId!==null&&$parent===null)throw new \DomainException('Assunto pai nao encontrado.');$this->taxonomy->assertMoveDoesNotCreateCycle($current->id,$input->parentId,$this->subjects);$name=trim($input->name);$slug=$this->taxonomy->slug($name);$duplicate=$this->subjects->findByParentAndSlug($input->parentId,$slug);if($duplicate!==null&&$duplicate->id!==$current->id)throw new \DomainException('Ja existe um assunto com este nome no mesmo nivel.');$updated=new TaxonomySubject($current->id,$input->parentId,$name,$slug,$input->description===null?null:trim($input->description),$parent===null?0:$parent->level+1,$current->active);$this->subjects->save($updated);return $this->mapper->toResponse($updated);});} }
